AND status_cd = '00A'
 1

SELECT , (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName", (SELECT b.user_role FROM bt_tenant_user b WHERE a.tenant_id = b.tenant_id AND b.status_cd = '00A' AND b.user_id = #{query.userId}) AS "userRole" FROM bt_tenant a WHERE 1=1 AND a.status_cd = '00A'
AND (a.tenant_code LIKE
#{query.searchContent}
OR a.tenant_name LIKE
#{query.searchContent}
)
AND a.space_id = #{query.spaceId}
ORDER BY updated_time DESC

SELECT , u.user_name, u.real_name, u.system_code, u.email, u.phone_no, u2.real_name AS updatorName, CASE WHEN u.create_tenant_id = #{query.tenantId} THEN 1 ELSE 0 END AS "isBelongCurrentTenant" FROM bt_tenant_user a JOIN bt_user u ON a.user_id = u.user_id LEFT JOIN bt_user u2 ON a.updator_id = u2.user_id WHERE a.status_cd = '00A'
AND (u.user_name LIKE
#{query.searchContent}
OR u.real_name LIKE
#{query.searchContent}
)
AND a.tenant_id = #{query.tenantId} ORDER BY a.updated_time DESC

SELECT a.tenant_id, a.tenant_code, a.tenant_name, b.user_role, a.system_type, c.space_id, c.space_name FROM bt_tenant a JOIN bt_tenant_user b ON a.tenant_id = b.tenant_id LEFT JOIN bt_workspace c ON a.space_id = c.space_id WHERE a.status_cd = '00A' AND b.status_cd = '00A' AND b.user_id = #{userId}
AND a.space_id = #{spaceId}
ORDER BY a.updated_time DESC

SELECT a.tenant_id, a.tenant_code, a.tenant_name, a.system_type, b.space_id, b.space_name FROM bt_tenant a LEFT JOIN bt_workspace b ON a.space_id = b.space_id WHERE a.status_cd = '00A' and (a.system_type IS NULL OR a.system_type != 'workspace')
AND a.space_id = #{spaceId}
ORDER BY a.updated_time DESC

